'use client';

import { useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { 
  Clock, 
  Gavel, 
  TrendingUp, 
  Users, 
  Eye,
  ArrowRight,
  Flame,
  MapPin,
  Calendar,
  Zap
} from 'lucide-react';
import { useTheme } from '@/lib/context/ThemeContext';
import Link from 'next/link';

interface AuctionCardProps {
  auction: {
    _id: string;
    startingBidEth: number;
    currentBidEth: number;
    bidIncrementEth: number;
    endTime: string;
    timeRemainingMs: number;
    timeRemainingFormatted: string;
    totalBids: number;
    uniqueBidders: number;
    views: number;
    status: string;
    eventId: {
      _id: string;
      title: string;
      date: string;
      venue: string;
      city?: string;
      image?: string;
      imageUrl?: string;
    };
    ticketTypeId: {
      name: string;
      description?: string;
    };
    minNextBidEth: number;
  };
  showBidButton?: boolean;
  highlight?: 'ending' | 'hot' | null;
}

export function AuctionCard({ auction, showBidButton = true, highlight = null }: AuctionCardProps) {
  const { theme } = useTheme();
  const isDark = theme === 'dark';
  const [timeRemaining, setTimeRemaining] = useState(auction.timeRemainingMs);

  // Live countdown
  useEffect(() => {
    if (timeRemaining <= 0) return;

    const interval = setInterval(() => {
      setTimeRemaining(prev => Math.max(0, prev - 1000));
    }, 1000);

    return () => clearInterval(interval);
  }, [timeRemaining]);

  const formatTimeDetailed = (ms: number): { value: string; unit: string; full: string } => {
    if (ms <= 0) return { value: '0', unit: 's', full: 'Ended' };
    
    const seconds = Math.floor(ms / 1000);
    const minutes = Math.floor(seconds / 60);
    const hours = Math.floor(minutes / 60);
    const days = Math.floor(hours / 24);
    
    if (days > 0) {
      return { 
        value: `${days}d ${hours % 24}h`, 
        unit: '', 
        full: `${days}d ${hours % 24}h ${minutes % 60}m` 
      };
    }
    if (hours > 0) {
      return { 
        value: `${hours}h ${minutes % 60}m`, 
        unit: '', 
        full: `${hours}h ${minutes % 60}m ${seconds % 60}s` 
      };
    }
    if (minutes > 0) {
      return { 
        value: `${minutes}m ${seconds % 60}s`, 
        unit: '', 
        full: `${minutes}m ${seconds % 60}s` 
      };
    }
    return { value: `${seconds}`, unit: 's', full: `${seconds}s` };
  };

  const isEndingSoon = timeRemaining > 0 && timeRemaining < 60 * 60 * 1000; // 1 hour
  const isHot = auction.totalBids >= 5 || auction.uniqueBidders >= 3;
  const hasNoBids = auction.currentBidEth === 0;
  const eventImage = auction.eventId?.image || auction.eventId?.imageUrl || '/placeholder-event.jpg';
  const timeInfo = formatTimeDetailed(timeRemaining);

  const formatDate = (dateStr: string) => {
    if (!dateStr) return 'TBD';
    const date = new Date(dateStr);
    return date.toLocaleDateString('en-IN', {
      day: 'numeric',
      month: 'short',
      year: 'numeric'
    });
  };

  return (
    <motion.div
      whileHover={{ y: -4, scale: 1.01 }}
      transition={{ duration: 0.2 }}
      className="h-full"
    >
      <Link href={`/auction/${auction._id}`} className="block h-full">
        <div className={`
          relative overflow-hidden rounded-2xl h-full
          ${isDark 
            ? 'bg-[#1A1A1A] border border-white/10' 
            : 'bg-white border border-gray-100 shadow-lg shadow-black/5'
          }
          transition-all duration-300 hover:shadow-xl
          ${isDark ? 'hover:border-orange-500/30' : 'hover:shadow-orange-500/10'}
        `}>
          
          {/* Hero Image Section */}
          <div className="relative h-48 overflow-hidden">
            <img
              src={eventImage}
              alt={auction.eventId?.title || 'Event'}
              className="w-full h-full object-cover"
            />
            
            {/* Dark gradient overlay for text readability */}
            <div className="absolute inset-0 bg-gradient-to-t from-black/90 via-black/40 to-black/20" />
            
            {/* Top badges row */}
            <div className="absolute top-3 left-3 right-3 flex items-start justify-between">
              <div className="flex flex-wrap gap-2">
                {/* Live Badge */}
                {timeRemaining > 0 && (
                  <div className="flex items-center gap-1.5 px-2.5 py-1 rounded-full bg-green-500/90 backdrop-blur-sm">
                    <span className="w-1.5 h-1.5 rounded-full bg-white animate-pulse" />
                    <span className="text-[10px] font-bold text-white tracking-wide">LIVE</span>
                  </div>
                )}
                
                {/* Status badges */}
                {(isEndingSoon || highlight === 'ending') && (
                  <div className="flex items-center gap-1 px-2.5 py-1 rounded-full bg-red-500/90 backdrop-blur-sm">
                    <Clock className="h-3 w-3 text-white" />
                    <span className="text-[10px] font-bold text-white">ENDING SOON</span>
                  </div>
                )}
                
                {(isHot || highlight === 'hot') && !isEndingSoon && (
                  <div className="flex items-center gap-1 px-2.5 py-1 rounded-full bg-gradient-to-r from-orange-500 to-amber-500 backdrop-blur-sm">
                    <Flame className="h-3 w-3 text-white" />
                    <span className="text-[10px] font-bold text-white">HOT</span>
                  </div>
                )}
                
                {hasNoBids && (
                  <div className="flex items-center gap-1 px-2.5 py-1 rounded-full bg-emerald-500/90 backdrop-blur-sm">
                    <Zap className="h-3 w-3 text-white" />
                    <span className="text-[10px] font-bold text-white">NO BIDS YET</span>
                  </div>
                )}
              </div>

              {/* Views counter */}
              <div className="flex items-center gap-1 px-2 py-1 rounded-full bg-black/50 backdrop-blur-sm">
                <Eye className="h-3 w-3 text-white/80" />
                <span className="text-[10px] font-medium text-white/80">{auction.views || 0}</span>
              </div>
            </div>

            {/* Event Info Overlay - Bottom of image */}
            <div className="absolute bottom-0 left-0 right-0 p-4">
              {/* Ticket Type Badge */}
              <div className="inline-flex items-center px-3 py-1 rounded-full bg-white/95 backdrop-blur-sm mb-2">
                <span className="text-xs font-semibold text-gray-800">
                  {auction.ticketTypeId?.name || 'General Admission'}
                </span>
              </div>
              
              {/* Event Title */}
              <h3 className="text-xl font-bold text-white leading-tight mb-2 drop-shadow-lg">
                {auction.eventId?.title || 'Event'}
              </h3>
              
              {/* Date & Location */}
              <div className="flex flex-wrap items-center gap-3 text-white/90 text-xs">
                <span className="flex items-center gap-1">
                  <Calendar className="h-3.5 w-3.5" />
                  {formatDate(auction.eventId?.date)}
                </span>
                {auction.eventId?.venue && (
                  <span className="flex items-center gap-1">
                    <MapPin className="h-3.5 w-3.5" />
                    {auction.eventId?.city || auction.eventId?.venue}
                  </span>
                )}
              </div>
            </div>
          </div>

          {/* Card Content */}
          <div className="p-4 space-y-4">
            
            {/* Bid Amount Section */}
            <div className="flex items-center justify-between">
              <div>
                <p className={`text-xs font-medium mb-1 ${isDark ? 'text-gray-500' : 'text-gray-500'}`}>
                  {hasNoBids ? 'Starting Bid' : 'Current Bid'}
                </p>
                <div className="flex items-center gap-2">
                  <div className={`p-1.5 rounded-lg ${isDark ? 'bg-green-500/20' : 'bg-green-50'}`}>
                    <TrendingUp className="h-4 w-4 text-green-500" />
                  </div>
                  <span className={`text-2xl font-bold ${isDark ? 'text-white' : 'text-gray-900'}`}>
                    {hasNoBids 
                      ? auction.startingBidEth?.toFixed(4) 
                      : auction.currentBidEth?.toFixed(4)
                    }
                  </span>
                  <span className="text-sm font-semibold text-orange-500">ETH</span>
                </div>
              </div>
              
              {!hasNoBids && (
                <div className="text-right">
                  <p className={`text-[10px] ${isDark ? 'text-gray-600' : 'text-gray-400'}`}>Min next</p>
                  <p className={`text-sm font-semibold ${isDark ? 'text-gray-400' : 'text-gray-600'}`}>
                    {auction.minNextBidEth?.toFixed(4)} ETH
                  </p>
                </div>
              )}
            </div>

            {/* Countdown Timer */}
            <div className={`
              flex items-center justify-between p-3 rounded-xl
              ${isEndingSoon 
                ? 'bg-gradient-to-r from-red-500/10 to-orange-500/10 border border-red-500/20' 
                : isDark 
                  ? 'bg-white/5 border border-white/10' 
                  : 'bg-gray-50 border border-gray-100'
              }
            `}>
              <div className="flex items-center gap-2">
                <Clock className={`h-4 w-4 ${isEndingSoon ? 'text-red-500 animate-pulse' : isDark ? 'text-gray-400' : 'text-gray-500'}`} />
                <span className={`text-xs font-medium ${isDark ? 'text-gray-400' : 'text-gray-600'}`}>
                  {timeRemaining > 0 ? 'Ends in' : 'Status'}
                </span>
              </div>
              <span className={`
                text-lg font-bold font-mono tracking-tight
                ${isEndingSoon 
                  ? 'text-red-500' 
                  : timeRemaining <= 0 
                    ? isDark ? 'text-gray-500' : 'text-gray-400'
                    : isDark ? 'text-white' : 'text-gray-900'
                }
              `}>
                {timeInfo.full}
              </span>
            </div>

            {/* Stats Row */}
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-4">
                <div className="flex items-center gap-1.5">
                  <div className={`p-1 rounded ${isDark ? 'bg-orange-500/20' : 'bg-orange-50'}`}>
                    <Gavel className="h-3.5 w-3.5 text-orange-500" />
                  </div>
                  <span className={`text-xs font-medium ${isDark ? 'text-gray-400' : 'text-gray-600'}`}>
                    {auction.totalBids || 0} Bids
                  </span>
                </div>
                <div className="flex items-center gap-1.5">
                  <div className={`p-1 rounded ${isDark ? 'bg-purple-500/20' : 'bg-purple-50'}`}>
                    <Users className="h-3.5 w-3.5 text-purple-500" />
                  </div>
                  <span className={`text-xs font-medium ${isDark ? 'text-gray-400' : 'text-gray-600'}`}>
                    {auction.uniqueBidders || 0} Bidders
                  </span>
                </div>
              </div>
            </div>

            {/* Action Button */}
            {showBidButton && timeRemaining > 0 && (
              <Button 
                className="w-full h-12 bg-gradient-to-r from-orange-500 to-orange-600 hover:from-orange-600 hover:to-orange-700 text-white font-bold text-sm rounded-xl border-0 shadow-lg shadow-orange-500/20 hover:shadow-orange-500/30 transition-all"
              >
                <Zap className="h-4 w-4 mr-2" />
                Place Bid
                <ArrowRight className="h-4 w-4 ml-2" />
              </Button>
            )}

            {timeRemaining <= 0 && (
              <Button 
                variant="outline" 
                className={`w-full h-12 rounded-xl font-semibold ${
                  isDark 
                    ? 'border-white/20 text-white hover:bg-white/10' 
                    : 'border-gray-200 text-gray-700 hover:bg-gray-50'
                }`}
              >
                View Results
                <ArrowRight className="h-4 w-4 ml-2" />
              </Button>
            )}
          </div>
        </div>
      </Link>
    </motion.div>
  );
}
